#' Bayesian Test of Deficit
#'
#' 
#' @param case .
#' @param controls .
#' @param sd .
#' @param sample_size .
#' @param alternative .
#' @param credible_interval .
#' @param credible_level .
#' @param iter .
#' @param seed .
#' @param show_plot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$resultsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$resultsTable$asDF}
#'
#' \code{as.data.frame(results$resultsTable)}
#'
#' @export
btd <- function(
    case = 35,
    controls = 50,
    sd = 10,
    sample_size = 20,
    alternative = "two.sided",
    credible_interval = TRUE,
    credible_level = 95,
    iter = 10000,
    seed = 42,
    show_plot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("btd requires jmvcore to be installed (restart may be required)")


    options <- btdOptions$new(
        case = case,
        controls = controls,
        sd = sd,
        sample_size = sample_size,
        alternative = alternative,
        credible_interval = credible_interval,
        credible_level = credible_level,
        iter = iter,
        seed = seed,
        show_plot = show_plot)

    analysis <- btdClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

